/* fw_yaffs_mkdir: yaffsfs.c yaffs_mkdir, 0x01A9A886.  F0106 (high).  0, or -1 when it exists
 * or cannot be made. The OS passes mode 0 (db2) or 0x4180 (tar). Thread context. */
typedef int fw_yaffs_mkdir_t(const char *path, int mode);
