/* fw_yaffs_stat: yaffsfs.c yaffs_stat, 0x01A9A688.  F0106 (high).  st: 13 words; mode in word
 * 2 (0x4000 folder, 0x8000 file), size in word 7. 0 or -1. Thread context. */
typedef int fw_yaffs_stat_t(const char *path, unsigned *st);
